const views=[...document.querySelectorAll('[data-view]')];views.forEach(button=>button.addEventListener('click',()=>{const map=button.dataset.view==='map';document.querySelector('#map-panel').hidden=!map;document.querySelector('#list-panel').hidden=map;views.forEach(b=>b.setAttribute('aria-pressed',String(b===button)))}));const search=document.querySelector('input[type=search]');if(search){const rows=[...document.querySelectorAll('.entry')];search.addEventListener('input',()=>{const q=search.value.trim().toLocaleLowerCase('uk');let count=0;rows.forEach(row=>{row.hidden=!row.dataset.search.toLocaleLowerCase('uk').includes(q);if(!row.hidden)count++});document.querySelector('.empty').hidden=count>0;document.querySelector('#result-count').textContent=`${count} із ${rows.length} розборів`})}
